INSERT INTO CustoEmpresa ( NumMovimento, EmpVinculada, CodigoParceiro, CodHistorico, DataMovto, ValorDebito, ValorCredito, Complemento, Plano1, Plano2, Plano3, ContaFinanceira, Confirmado, Integracao, DataPagto, DataVencto, MovPagtoLote, SelPagtoLote, Observacao, NumDoc, CodImovel, AgrupadorVenda, ClassificacaoVenda, SofreReajuste, IndiceReajuste, CodAtribuiParceiro, CodAtribuiEmpresa, CodAnteriorParceiro, CodAnteriorEmpresa, Efetuado, LinkVenda, PagoAntecipado, ValorReajustado, ReferenteNotaFiscal, PagamentoLote, PadraoRelatorio, SomenteIntegracao, AnoOcorrenciaMensal, MesOcorrenciaMensal, EmitirCheque, ChequeEmitido, ValorOriginalImovel, CodigoCondPagto )
SELECT ArquivoMorto.NumMovimento, ArquivoMorto.EmpVinculada, ArquivoMorto.CodigoParceiro, ArquivoMorto.CodHistorico, ArquivoMorto.DataMovto, ArquivoMorto.ValorDebito, ArquivoMorto.ValorCredito, ArquivoMorto.Complemento, ArquivoMorto.Plano1, ArquivoMorto.Plano2, ArquivoMorto.Plano3, ArquivoMorto.ContaFinanceira, ArquivoMorto.Confirmado, ArquivoMorto.Integracao, ArquivoMorto.DataPagto, ArquivoMorto.DataVencto, ArquivoMorto.MovPagtoLote, ArquivoMorto.SelPagtoLote, ArquivoMorto.Observacao, ArquivoMorto.NumDoc, ArquivoMorto.CodImovel, ArquivoMorto.AgrupadorVenda, ArquivoMorto.ClassificacaoVenda, ArquivoMorto.SofreReajuste, ArquivoMorto.IndiceReajuste, ArquivoMorto.CodAtribuiParceiro, ArquivoMorto.CodAtribuiEmpresa, ArquivoMorto.CodAnteriorParceiro, ArquivoMorto.CodAnteriorEmpresa, ArquivoMorto.Efetuado, ArquivoMorto.LinkVenda, ArquivoMorto.PagoAntecipado, ArquivoMorto.ValorReajustado, ArquivoMorto.ReferenteNotaFiscal, ArquivoMorto.PagamentoLote, ArquivoMorto.PadraoRelatorio, ArquivoMorto.SomenteIntegracao, ArquivoMorto.AnoOcorrenciaMensal, ArquivoMorto.MesOcorrenciaMensal, ArquivoMorto.EmitirCheque, ArquivoMorto.ChequeEmitido, ArquivoMorto.ValorOriginalImovel, ArquivoMorto.CodigoCondPagto
FROM ArquivoMorto
WHERE (((ArquivoMorto.EmpVinculada)=Formulários![Relatorio Custos Empresa2]!CodigoVinculada) And ((ArquivoMorto.Plano1)<>1) And ((ArquivoMorto.SomenteIntegracao)=False));
